10	/**
11	 * Rejects a create whose email domain is a known disposable-mail provider, before
12	 * {@link SaveOwner} runs. Handled with 400 by {@code MissingOwnerFieldsHandler}, the
13	 * same 400 path {@link BuildOwner} uses for a malformed email. An absent email is left
14	 * untouched.
15	 */
16	public class CheckEmailDomain {
17	
18	    private static final Set<String> BLOCKED = Set.of(
19	            "mailinator.com", "tempmail.com", "guerrillamail.com");
20	
21	    public void service(@Val Owner owner) throws MissingOwnerFieldsException {
22	        String email = owner.getEmail();
23	        if (email == null) {
24	            return;
25	        }
26	        int at = email.lastIndexOf('@');
27	        if (at >= 0 && BLOCKED.contains(email.substring(at + 1).toLowerCase())) {
28	            throw new MissingOwnerFieldsException(List.of("email"));
29	        }
30	    }
31	}
