5	import java.security.NoSuchAlgorithmException;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Assigns a deterministic {@code householdId} derived from the owner's normalized
12	 * lastName and postcode, so every owner sharing a lastName and postcode resolves to the
13	 * same identifier automatically. Runs before the household and identity checks.
14	 */
15	public class AssignHouseholdId {
16	
17	    public void service(@Val Owner owner) {
18	        String postcode = owner.getPostcode();
19	        String key = CheckUniqueHousehold.normalize(owner.getLastName())
20	                + "|" + (postcode == null ? "" : postcode);
21	        owner.setHouseholdId(hash(key));
22	    }
23	
24	    /** First 6 bytes (12 hex chars) of SHA-256({@code key}) as lower-case hex — stable across requests. */
25	    static String hash(String key) {
26	        try {
27	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
28	            StringBuilder sb = new StringBuilder(12);
29	            for (int i = 0; i < 6; i++) {
30	                sb.append(String.format("%02x", digest[i]));
31	            }
32	            return sb.toString();
33	        }
34	        catch (NoSuchAlgorithmException e) {
35	            throw new IllegalStateException(e);
36	        }
37	    }
38	}
