6	import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
7	
8	/**
9	 * Rejects a create whose computed {@code householdId} (derived from lastName and postcode)
10	 * already belongs to another owner, before {@link SaveOwner} runs. Handled with 409 by
11	 * {@code DuplicateHouseholdHandler}. Skipped when the request opts in with
12	 * {@code sharesHousehold=true}, so a declared household member is created instead.
13	 */
14	public class CheckUniqueHousehold {
15	
16	    public void service(@Val Owner owner, @Val Boolean sharesHousehold, OwnerRepository ownerRepository)
17	            throws DuplicateHouseholdException {
18	        if (Boolean.TRUE.equals(sharesHousehold)) {
19	            return;
20	        }
21	        String householdId = owner.getHouseholdId();
22	        for (Owner other : ownerRepository.findAll()) {
23	            if (!other.getId().equals(owner.getId())
24	                    && householdId.equals(other.getHouseholdId())) {
25	                throw new DuplicateHouseholdException(owner.getLastName(), owner.getPostcode());
26	            }
27	        }
28	    }
29	
30	    /** Lower-cases and collapses runs of whitespace to a single space so that
31	     *  case and spacing differences do not defeat the household match. */
32	    static String normalize(String value) {
33	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
34	    }
35	}
