7	
8	/**
9	 * Rejects a create whose whole {@code identityKey} already belongs to another owner,
10	 * before {@link SaveOwner} runs. Consolidates the former telephone, email and household
11	 * duplicate checks: only an exact full-key match is a duplicate, so two members of the
12	 * same household with different telephones are both allowed. Handled with 409 by
13	 * {@code DuplicateIdentityHandler}. Runs after {@link AssignHouseholdId} so the key can
14	 * include the household part.
15	 */
16	public class CheckUniqueIdentity {
17	
18	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
19	            throws DuplicateIdentityException {
20	        String key = identityKey(owner);
21	        for (Owner other : ownerRepository.findAll()) {
22	            if (!other.getId().equals(owner.getId()) && key.equals(identityKey(other))) {
23	                throw new DuplicateIdentityException(key);
24	            }
25	        }
26	    }
27	
28	    /** Derived duplicate key: normalizedTelephone + '|' + (email or empty) + '|' + householdId. */
29	    public static String identityKey(Owner owner) {
30	        return blank(owner.getTelephone()) + "|" + blank(owner.getEmail()) + "|"
31	                + blank(owner.getHouseholdId());
32	    }
33	
34	    private static String blank(String value) {
35	        return value == null ? "" : value;
36	    }
37	}
