13	
14	    static final int CAPACITY = 50;
15	
16	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
17	            throws CityAtCapacityException {
18	        String city = normalize(owner.getCity());
19	        long count = ownerRepository.findAll().stream()
20	                .filter(other -> !other.getId().equals(owner.getId()))
21	                .filter(other -> city.equals(normalize(other.getCity())))
22	                .count();
23	        if (count >= CAPACITY) {
24	            throw new CityAtCapacityException(owner.getCity());
25	        }
26	    }
