11	/**
12	 * Rolls the effective registrationDate (supplied or defaulted) forward to the next
13	 * Monday when it lands on a weekend, before {@link CheckDailyLimit} counts by it and the
14	 * membership number derives its year segment from it.
15	 */
16	public class AdjustRegistrationDate {
17	
18	    public void service(@Val Owner owner) throws MissingOwnerFieldsException {
19	        LocalDate date = owner.getRegistrationDate();
20	        if (date.isAfter(LocalDate.now())) {
21	            throw new MissingOwnerFieldsException(List.of("registrationDate"));
22	        }
23	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
24	            date = date.plusDays(1);
25	        }
26	        owner.setRegistrationDate(date);
27	    }
28	}
