22	    private static String hash8(String input) {
23	        try {
24	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(input.getBytes(StandardCharsets.UTF_8));
25	            StringBuilder sb = new StringBuilder(16);
26	            for (int i = 0; i < 4; i++) {
27	                sb.append(String.format("%02X", digest[i]));
28	            }
29	            return sb.toString();
30	        }
31	        catch (NoSuchAlgorithmException ex) {
32	            throw new IllegalStateException(ex);
33	        }
34	    }
35	
