12	public class AssignNamesakeCount {
13	
14	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
15	        String firstName = normalize(owner.getFirstName());
16	        String lastName = normalize(owner.getLastName());
17	        int count = 0;
18	        for (Owner other : ownerRepository.findAll()) {
19	            if (firstName.equals(normalize(other.getFirstName()))
20	                    && lastName.equals(normalize(other.getLastName()))) {
21	                count++;
22	            }
23	        }
24	        owner.setNamesakeCount(count);
25	    }
26	
27	    private static String normalize(String value) {
28	        return value == null ? "" : value.trim().toLowerCase();
29	    }
