3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Records a soft-duplicate match before {@link SaveOwner} runs. The create has already
9	 * passed {@link CheckUniqueIdentity}, so it is not a hard duplicate. When it still shares
10	 * an existing owner's lastName (compared case-insensitively with collapsed whitespace)
11	 * and postcode but carries a different telephone, the matched owner's id is stored on
12	 * {@code possibleDuplicateOf}, which surfaces as {@code possibleDuplicate}/{@code
13	 * possibleDuplicateOf} on the response. Left unset (so {@code possibleDuplicate} is false)
14	 * otherwise, and always for a declared household member ({@code sharesHousehold=true}),
15	 * which is not a suspected duplicate.
16	 */
17	public class FlagPossibleDuplicate {
18	
19	    public void service(@Val Owner owner, @Val Boolean sharesHousehold, OwnerRepository ownerRepository) {
20	        String postcode = owner.getPostcode();
21	        if (postcode == null || Boolean.TRUE.equals(sharesHousehold)) {
22	            return;
23	        }
24	        String lastName = CheckUniqueHousehold.normalize(owner.getLastName());
25	        for (Owner other : ownerRepository.findAll()) {
26	            if (!other.getId().equals(owner.getId())
27	                    && postcode.equals(other.getPostcode())
28	                    && lastName.equals(CheckUniqueHousehold.normalize(other.getLastName()))
29	                    && !postcode.isBlank()
30	                    && !equalsTelephone(owner, other)) {
31	                owner.setPossibleDuplicateOf(other.getId());
32	                return;
33	            }
34	        }
35	    }
36	
37	    private static boolean equalsTelephone(Owner owner, Owner other) {
38	        String telephone = owner.getTelephone();
39	        return telephone != null && telephone.equals(other.getTelephone());
40	    }
41	}
