5	/**
6	 * Normalizes a raw address to the stored/returned form: trims and collapses whitespace,
7	 * upper-cases, and expands common abbreviations (ST->STREET, RD->ROAD, AVE->AVENUE).
8	 * Returns "" for a null or blank-after-trim address so callers can reject it as missing.
9	 */
10	public final class AddressNormalizer {
11	
12	    private static final Map<String, String> ABBREV = Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
13	
14	    private AddressNormalizer() {
15	    }
16	
17	    public static String normalize(String value) {
18	        if (value == null) {
19	            return "";
20	        }
21	        StringBuilder sb = new StringBuilder();
22	        for (String word : value.trim().toUpperCase().split("\\s+")) {
23	            if (word.isEmpty()) {
24	                continue;
25	            }
26	            if (sb.length() > 0) {
27	                sb.append(' ');
28	            }
29	            sb.append(ABBREV.getOrDefault(word, word));
30	        }
31	        return sb.toString();
32	    }
33	}
